422	public class ValidatePaste {
423	    // Every line is checked before any is added: name,amount,date,note — the name a person on the sheet (ignoring
424	    // case and surrounding spaces), the rest by the claim form's rules (a blank date is the entry date, else the sheet's today, the note
425	    // may hold commas or be absent). Blank lines are skipped; a paste with no line is refused.
426	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteRequest body, People people,
427	            Settings settings, Holidays holidays, Periods periods, Out<PastedLines> out)
428	            throws InvalidClaimException, ClaimInClosedPeriodException, ClaimAfterRetirementException {
429	        String sheet = sheetId.trim();
430	        String text = body == null || body.text() == null ? "" : body.text();
431	        List<PastedLine> lines = new ArrayList<>();
432	        int n = 0;
433	        for (String line : text.split("\\r?\\n")) {
434	            n++;
435	            if (line.isBlank()) {
436	                continue;
437	            }
438	            String[] fields = line.split(",", 4);
439	            if (fields.length < 2) {
440	                throw new InvalidClaimException("Line " + n + ": type name,amount,date,note.");
441	            }
442	            String name = fields[0].trim();
443	            Person person = name.isEmpty() ? null : people.findByName(sheet, name);
444	            if (person == null) {
445	                throw new InvalidClaimException("Line " + n + ": no person " + name + " on this sheet.");
446	            }
447	            ClaimInput input;
448	            try {
449	                input = ValidateClaim.parse(new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "",
450	                        fields.length > 3 ? fields[3] : "", ""));
451	            } catch (InvalidClaimException e) {
452	                throw new InvalidClaimException("Line " + n + ": " + e.getMessage());
453	            }
454	            LocalDate date = input.date() != null ? input.date() : settings.entryDate(sheet);
455	            LocalDate dueBy = holidays.dueBy(sheet, date, person.termsOn(date, settings));
456	            Period closed = periods.closedOn(sheet, dueBy);
457	            if (closed != null) {
458	                throw new ClaimInClosedPeriodException("Line " + n + ": the period " + closed.name()
459	                        + " is closed: no claim due by " + dueBy + " can be added.");
460	            }
461	            RefuseRetiredInput.check(person, date);
462	            lines.add(new PastedLine(person, input));
463	        }
464	        if (lines.isEmpty()) {
465	            throw new InvalidClaimException("Paste at least one line of name,amount,date,note.");
466	        }
467	        out.set(new PastedLines(lines));
468	    }
469	}
