567	-- decimals; claim_date defaults to the sheet's today when the claim is made.
568	CREATE TABLE claim (
569	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
570	    sheet_id   VARCHAR(255)   NOT NULL,
571	    person_id  BIGINT         NOT NULL REFERENCES person (id),
572	    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
573	    claim_date DATE           NOT NULL,
574	    note       VARCHAR(4000)  NOT NULL
575	);
576	CREATE INDEX claim_sheet ON claim (sheet_id, id);
577	-- An OPEN or PENDING claim can be reminded, once per sheet's today: the last sheet's today a reminder was written
578	-- (null: never reminded). Kept in the claim's history too (see V39). The journal trigger is made again around the
579	-- change: altering the table copies it, and a trigger left on would keep naming the copy's history.
580	DROP TRIGGER claim_journal;
581	ALTER TABLE claim ADD COLUMN reminded_on DATE;
582	ALTER TABLE claim_history ADD COLUMN reminded_on DATE;
583	CREATE TRIGGER claim_journal AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
